func (b *MoveTableCopyInsertQueryBuilder) BuildQuery(values []*ColumnValues) (string, []any, error) {
	var explodedArgs []any
	var builder strings.Builder
	builder.WriteString(b.preparedStatement)
	for i, value := range values {
